pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Provide 1 ether to the test contract for the lockInGuess call
        vm.deal(address(this), 1 ether);

        // Call lockInGuess with the guess
        c.lockInGuess(guess);

        // Record the contract balance before settle
        uint balanceBefore = address(c).balance;

        // Need to advance to the next block to allow settle
        vm.roll(block.number + 2);

        // Call settle
        c.settle();

        // The rule: if the guess was correct (which we cannot directly check without revealing state),
        // the balance should decrease by 2 ether; otherwise, it should stay the same.
        // Since we control the guess, we can compute the expected answer
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        uint expectedDecrease = (guess == answer) ? 2 ether : 0;

        uint balanceAfter = address(c).balance;
        assertTrue(balanceBefore - balanceAfter == expectedDecrease, "Balance change mismatch");
    }
}

