pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockOffset) public {
        // Ensure blockOffset is at least 1 (to satisfy block.number > guesses[msg.sender].block)
        blockOffset = bound(blockOffset, 1, 1000);
        vm.deal(address(this), 2 ether);

        // Lock in the guess with 1 ether
        c.lockInGuess{value: 1 ether}(guess);

        // Mine blocks to satisfy the block.number condition
        vm.roll(block.number + blockOffset);

        // Get the contract balance before settle
        uint256 balanceBefore = address(c).balance;

        // Call settle
        c.settle();

        // Get the contract balance after settle
        uint256 balanceAfter = address(c).balance;

        // The general rule: if the guess matches the blockhash, the caller should receive 2 ether
        // Since we cannot know the blockhash ahead of time, we check: balance should decrease by 2 ether
        // only when the guess equals the correct answer. For incorrect guesses, balance stays same.
        // However, we don't know if guess is correct. So we use: balance decrease <= 2 ether
        // But the mutant gives 2 ether when guess is WRONG, so balance could decrease by 2 ether in that case too.
        // Actually, we need a rule that P satisfies and M breaks.
        // M breaks: when guess == correct answer, P gives 2 ether, M gives 0.
        // So we check: if guess == correct answer, balance should decrease by 2 ether.
        // But we cannot know the correct answer. So we use a different approach:
        // For any guess, the balance decrease is either 0 or 2 ether.
        // In P: decrease=2 ether iff guess == correct, else 0.
        // In M: decrease=2 ether iff guess != correct, else 0.
        // So one general rule P satisfies but M doesn't: 
        // There exists a guess that makes balance decrease by 2 ether (any guess could be correct).
        // But that's existential, not universal. 

        // Better rule: P always sends money only for correct guess, M always sends only for wrong guess.
        // We can test: if we call settle twice, P will only send once (if first was correct, second won't work since block=0).
        // M similarly. Need a different approach.

        // Let's use: After calling settle, the contract balance must be >= 0 (always true) - not useful.

        // Actually, we can test: The function settle should never increase the caller's balance if the guess is wrong.
        // In P: caller balance only increases on correct guess. In M: caller balance only increases on wrong guess.
        // So we can test: if the guess is wrong, balance doesn't change. But we don't know if guess is wrong.

        // Simpler: The balance change after settle is always 0 or 2 ether. That's true for both.

        // Let me think differently. The key difference: the condition is inverted.
        // We can test: settle() should never transfer 2 ether AND also have the guess be wrong.
        // In P: if transfer happens, guess must be correct. 
        // In M: if transfer happens, guess must be wrong.
        // So P satisfies: transfer => guess == correct.  M breaks this.
        // How to know if guess was correct? We can compute it!

        // Actually, we can pre-compute the block hash and compare.
        // But blockhash is only available for the current block or recent ones. 
        // Since we mine forward, the blockhash for guesses[msg.sender].block is available.

        // We know the block number where the hash was locked: block.number when we called lockInGuess.
        // But we don't have access to block.number at that time.

        // Alternative: Use vm.prank to isolate callers and test that settle never reverts and never transfers when guess is wrong.
        // But we still need to know if guess is correct.

        // Let's try: The function settle should never send 2 ether to a caller who locked in a random guess.
        // Since random guess is almost certainly wrong, P sends 0, M sends 2. 
        // So we can check: after settle, the caller's balance increased by 0 (if guess wrong) or 2 (if correct).
        // But we don't know if our random guess happens to be correct (very unlikely).
        // To make it deterministic, we can compute the expected answer and set guess to something.

        // Best approach: Compute the expected answer from the blockhash that will be used.
        vm.roll(block.number + 1);  // Ensure we have a future block
        uint256 targetBlock = block.number + blockOffset;
        // But lockInGuess sets guesses[msg.sender].block = block.number + 1 at time of call.
        // So if we call lockInGuess now, it will use block.number+1 after we roll.
        // This is getting complicated. Let's use a simpler deterministic test:

        // Actually, we can just check: After valid calls, the total balance change of the caller is always 0 or 2.
        // This is true for both contracts, not a discriminator.

        // Let's use the approach: P always sends exactly 2 ether if and only if guess == answer.
        // M sends exactly 2 ether if and only if guess != answer.
        // So we test: after settle, caller balance increase == 2 ether iff our guess matched the correct answer.
        // But we can't know if it matched.

        // Wait - we can compute answer inside the test! keccak256(abi.encodePacked(blockhash(targetBlock)))
        // But we need to know targetBlock, which is block.number at lockInGuess + 1.

        // Let's restructure:
        // First, record current block: startBlock = block.number
        // Call lockInGuess (which sets block = startBlock + 1)
        // Then roll to startBlock + 2
        // Compute answer = keccak256(abi.encodePacked(blockhash(startBlock + 1)))
        // Then call settle
        // Check: if guess == answer, balance should decrease by 2 in P, not in M

        vm.deal(address(this), 2 ether);
        uint256 startBlock = block.number;
        c.lockInGuess{value: 1 ether}(guess);
        vm.roll(startBlock + 2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(startBlock + 1)));
        uint256 balanceBefore = address(c).balance;
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // In reference P: if guess == answer, balance decreases by 2; else unchanged.
        // In mutant M: if guess != answer, balance decreases by 2; else unchanged.
        // So the rule "balance should only decrease when guess equals answer" holds for P but not M.
        assertTrue(balanceAfter >= balanceBefore - 2 ether); // Always true
        if (guess == answer) {
            assertTrue(balanceBefore - balanceAfter == 2 ether); // P: true, M: false
        } else {
            assertTrue(balanceBefore == balanceAfter); // P: true, M: false (M would send 2)
        }
    }
}

