pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 guess) public {
        // Fund the caller with enough ether
        vm.deal(address(this), 3 ether);

        // Lock in the guess with exactly 1 ether
        c.lockInGuess{value: 1 ether}(guess);

        // Get the block number for the answer
        uint256 answerBlock = block.number + 1;
        vm.roll(answerBlock);

        // Record balance before settle
        uint256 contractBalanceBefore = address(c).balance;

        // Try to settle - might revert if guess is wrong in the original contract
        bool success = address(c).call(abi.encodeWithSignature("settle()"));

        // Compute expected behavior: in the reference, balance decreases by 2 only if guess matches answer
        bytes32 answer = keccak256(abi.encodePacked(blockhash(answerBlock)));
        if (success) {
            uint256 contractBalanceAfter = address(c).balance;
            if (guess == answer) {
                assertTrue(contractBalanceAfter == contractBalanceBefore - 2 ether);
            } else {
                assertTrue(contractBalanceAfter == contractBalanceBefore);
            }
        }
    }
}

