pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 salt) public {
        vm.assume(salt != 0); // prevent trivial blockhash reuse
        // Fund caller with at least 1 ether
        vm.deal(address(this), 2 ether);
        // First lock in a guess (must pay 1 ether)
        c.lockInGuess{value: 1 ether}(guess);
        // Advance to the settlement block
        uint256 targetBlock = block.number + 1;
        vm.roll(targetBlock + 1);
        // Record balance before settle
        uint256 balBefore = address(this).balance;
        // Settle
        c.settle();
        uint256 balAfter = address(this).balance;
        // The rule: if the guess was correct, balance increases by exactly 1 ether;
        // otherwise no transfer (balance unchanged). We cannot know if guess matches
        // future blockhash, but we can express the rule as:
        // (balAfter - balBefore) is either 0 or 1 ether.
        uint256 diff = balAfter - balBefore;
        assertTrue(diff == 0 || diff == 1 ether);
    }
}

