        // Advance to after the guess block
        vm.roll(block.number + 2);

        // Record caller's balance before settle
        uint256 balanceBefore = address(this).balance;

        // Try to settle; it might revert in M but not in P
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        uint256 balanceAfter = address(this).balance;

        // General rule: if settle() succeeds, balance must increase by 0 or 2 ether
